import React, { Suspense } from "react";
import { Navigate, Route, Routes } from "react-router-dom";

const AdminDashboard = React.lazy(() => import("./pages/AdminDashboard"));
const AdminBookings = React.lazy(() => import("./pages/AdminBookings"));
const AdminSchedule = React.lazy(() => import("./pages/AdminSchedule"));
const AdminHistory = React.lazy(() => import("./pages/AdminHistory"));
const ClientDashboard = React.lazy(() => import("./pages/ClientDashboard"));
const Login = React.lazy(() => import("./pages/Login"));
const Register = React.lazy(() => import("./pages/Register"));

const decodeToken = (token) => {
  const base64Value = token.split(".")[1];
  const normalized = base64Value.replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized.padEnd(normalized.length + ((4 - (normalized.length % 4)) % 4), "=");

  return JSON.parse(atob(padded));
};

const readTokenPayload = () => {
  const token = localStorage.getItem("token");
  if (!token) {
    return null;
  }

  try {
    const payload = decodeToken(token);
    return { token, payload };
  } catch (error) {
    localStorage.removeItem("token");
    return null;
  }
};

const ProtectedRoute = ({ allowedRole, children }) => {
  const auth = readTokenPayload();

  if (!auth) {
    return <Navigate to="/login" replace />;
  }

  if (auth.payload.role !== allowedRole) {
    return <Navigate to={auth.payload.role === "admin" ? "/admin" : "/"} replace />;
  }

  return children;
};

const DefaultRoute = () => {
  const auth = readTokenPayload();

  if (!auth) {
    return <Navigate to="/login" replace />;
  }

  return <Navigate to={auth.payload.role === "admin" ? "/admin" : "/"} replace />;
};

function App() {
  return (
    <Suspense fallback={<div className="app-loader"><div className="skeleton-line" /></div>}>
      <Routes>
        <Route
          path="/"
          element={
            <ProtectedRoute allowedRole="client">
              <ClientDashboard view="overview" />
            </ProtectedRoute>
          }
        />
        <Route
          path="/new-booking"
          element={
            <ProtectedRoute allowedRole="client">
              <ClientDashboard view="new-booking" />
            </ProtectedRoute>
          }
        />
        <Route
          path="/my-bookings"
          element={
            <ProtectedRoute allowedRole="client">
              <ClientDashboard view="my-bookings" />
            </ProtectedRoute>
          }
        />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="/client" element={<DefaultRoute />} />
        <Route
          path="/admin"
          element={
            <ProtectedRoute allowedRole="admin">
              <AdminDashboard />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/bookings"
          element={
            <ProtectedRoute allowedRole="admin">
              <AdminBookings />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/schedule"
          element={
            <ProtectedRoute allowedRole="admin">
              <AdminSchedule />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin/history"
          element={
            <ProtectedRoute allowedRole="admin">
              <AdminHistory />
            </ProtectedRoute>
          }
        />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Suspense>
  );
}

export default App;
